import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"AI 研究","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/AI_Research.md","filePath":"ai-dive/AI_Research.md","lastUpdated":null}'),o={name:"ai-dive/AI_Research.md"};function n(p,e,l,h,s,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-研究" tabindex="-1">AI 研究 <a class="header-anchor" href="#ai-研究" aria-label="Permalink to &quot;AI 研究&quot;">​</a></h1><p>后天的钱，是你几年之后能赚到的钱。</p><p>几年之后的市场环境可能跟今天大不一样，所以提前就要做好准备，始终具备领先于别人的基础能力。</p><p>华为提前10年研发5G技术，就是为了赚后天的钱。</p><p>在公司里，研究部门负责赚后天的钱。<a href="https://zhuanlan.zhihu.com/p/362671941" target="_blank" rel="noreferrer">2</a></p><h2 id="国际上ai机构哪家强" tabindex="-1">国际上AI机构哪家强？ <a class="header-anchor" href="#国际上ai机构哪家强" aria-label="Permalink to &quot;国际上AI机构哪家强？&quot;">​</a></h2><p>DeepMind、OpenAI和FAIR。</p><p>需要说明的是，这三家实验室都是属于纯AI研究实验室，但“背靠大树好乘凉”，这三家顶级AI实验室背后都有“金主”，分别背靠着谷歌、微软和Facebook等互联网及软件巨头。</p><h3 id="deepmind" tabindex="-1">DeepMind <a class="header-anchor" href="#deepmind" aria-label="Permalink to &quot;DeepMind&quot;">​</a></h3><p>DeepMind原来是一家英国的人工智能公司，公司创建于2010年，最初名称是DeepMind科技（DeepMind Technologies Limited），在2014年被谷歌收购。</p><p>谷歌每年都会给DeepMind拨款数亿美元，微软在OpenAI创始投资者10亿美元的基础上也投资了10亿美元，Facebook未对 FAIR的投资资金进行分类，但也是耗资不菲。</p><p>DeepMind 最出名的是 AlphaGo ，它在围棋游戏中挑战并击败了世界上最好的人类棋手，甚至还有一部关于 AlphaGo 战胜韩国围棋传奇李世石的 Netflix 纪录片。</p><h3 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><p>OpenAI成立于2015年底，总部位于旧金山，其创始人是特斯拉CEO埃隆·马斯克（没错，就是现在的世界首富）、Y Combinator总裁阿尔特曼、天使投资人彼得·泰尔（Peter Thiel）以及其他硅谷巨头，最初成立它的动机是出于对强人工智能潜在风险的担忧。</p><p>OpenAI 开发了游戏人工智能软件，已经在诸多等游戏中击败人类。然而，它更为出名的则是自然语言处理预处理模型GPT-3和人工智能图像生成器 DALL-E，这些软件已经达到了可以思考人生、生成的图像可以假乱真的地步。</p><h3 id="fair" tabindex="-1">FAIR <a class="header-anchor" href="#fair" aria-label="Permalink to &quot;FAIR&quot;">​</a></h3><p>FAIR成立的想法开始于 2013 年，Facebook的创始人扎克伯格，首席技术官 Mike Schroepfer 以及公司其他持有股票的领导，都在寻找着未来 10 到 20 年让公司保持竞争力的技术，包括计算机视觉、自然语言处理和对话型AI等。</p><p>为了更好地理解FAIR与Facebook的关系，举个例子，其实就相当于国内“达摩院”与阿里巴巴的关系。<a href="https://www.weiyangx.com/379999.html" target="_blank" rel="noreferrer">1</a></p><h2 id="论文写作" tabindex="-1">论文写作 <a class="header-anchor" href="#论文写作" aria-label="Permalink to &quot;论文写作&quot;">​</a></h2><p><a href="https://tobiaslee.top/2018/04/03/How-to-Write-a-Paper/" target="_blank" rel="noreferrer">https://tobiaslee.top/2018/04/03/How-to-Write-a-Paper/</a></p><p>北京十大推动中国科技发展的人工智能实验室：<a href="https://blog.csdn.net/yoggieCDA/article/details/102803735?utm_medium=distribute.pc_relevant.none-task-blog-2%7Edefault%7EOPENSEARCH%7Edefault-6.baidujs&amp;dist_request_id=&amp;depth_1-utm_source=distribute.pc_relevant.none-task-blog-2%7Edefault%7EOPENSEARCH%7Edefault-6.baidujs" target="_blank" rel="noreferrer">https://blog.csdn.net/yoggieCDA/article/details/102803735?utm_medium=distribute.pc_relevant.none-task-blog-2~default~OPENSEARCH~default-6.baidujs&amp;dist_request_id=&amp;depth_1-utm_source=distribute.pc_relevant.none-task-blog-2~default~OPENSEARCH~default-6.baidujs</a></p><h2 id="开源软件" tabindex="-1">开源软件 <a class="header-anchor" href="#开源软件" aria-label="Permalink to &quot;开源软件&quot;">​</a></h2><p>中国人工智能开源软件发展白皮书：<a href="http://www.aioss.cn/" target="_blank" rel="noreferrer">http://www.aioss.cn/</a></p><h2 id="论文" tabindex="-1">论文 <a class="header-anchor" href="#论文" aria-label="Permalink to &quot;论文&quot;">​</a></h2><p>AI领域的论文大多都在arXiv，很容易找到。大量的论文排山倒海，让人在兴奋的同时，也有点喘不过气。于是，有些善良的业内人士，提供了披沙拣金的有效途径——</p><p>Andrej Karpathy建起了”arXiv Sanity Preserver”，帮助大家对论文进行分类筛选，搜索，以及特征过滤。Miles Brundage以前也经常在推特上，发一些经过轻度炮制的arXiv论文清单，单子大概率是AI列的。</p><p>还有很多其他推友，非常乐于分享他们看到的有趣论文。这里是我可爱的关注列表：</p><p><a href="https://twitter.com/tomssilver/following" target="_blank" rel="noreferrer">https://twitter.com/tomssilver/following</a></p><p>如果喜欢Reddit的话，当然要关注r/MachineLearning。不过，上面的内容还是更适合吃瓜群众动手实践，对于学术研究的帮助可能小一些。</p><p>另外，大会上发表的论文是有必要看看的。NIPS、ICML以及ICLR是重中之重，其他有名的大会还包括AAAI、IJCAI和UAI等等。</p><p>分方向来说，计算机视觉会议有CVPR、ECCV和ICCV；自然语言会议有ACL、EMNLP以及NAACL；说到机器人，就是CoRL、ICAPS、ICRA、IROS和RSS。要看理论研究的话，AISTATS、COLT和KDD都是不错的选择。[3]</p><h2 id="python-库" tabindex="-1">Python 库 <a class="header-anchor" href="#python-库" aria-label="Permalink to &quot;Python 库&quot;">​</a></h2><p>终于把所有的Python库，都整理出来啦！ - IT界的小公举的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/385817966" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/385817966</a></p><p>真正的科研应该是什么样的？ - 一个科学家的回答 - 知乎 <a href="https://www.zhihu.com/question/264668384/answer/2010466280" target="_blank" rel="noreferrer">https://www.zhihu.com/question/264668384/answer/2010466280</a></p><p>[3]:</p>',35)])])}const A=a(o,[["render",n]]);export{u as __pageData,A as default};
